sysauto_script.script:
(function () {
    // Get today's time and date
    var rightNow = new GlideDateTime();

    // Calculate 24 hours from now
    var twentyFourHoursFromNow = new GlideDateTime();
    twentyFourHoursFromNow.addSeconds(24 * 60 * 60);

    // Query the database for NeedIt Task records with Due date field values
    // between now and 24 hours from now.  Only return NeedIt Task records
    // that do not have a State field value of Closed Complete.
    var dueSoonNITasks = new GlideRecord('x_58872_needit_needit_task');
    dueSoonNITasks.addQuery('due_date', '>=', rightNow.getDisplayValue());
    dueSoonNITasks.addQuery('due_date', '<=', twentyFourHoursFromNow.getDisplayValue());
    dueSoonNITasks.addQuery('state', '!=', 3);

    dueSoonNITasks.query();
    // Generate the dueSoonNeedItTasks event for each NeedIt Task record due soon
    while (dueSoonNITasks.next()) {
        gs.info("NeedIt Task due soon record = " + dueSoonNITasks.number);
        gs.eventQueue('x_58872_needit.dueSoonNeedItTasks', dueSoonNITasks, dueSoonNITasks.number, '');
    }
})();
